"""Corrected grammar examples: no invented idioms or stylistic synonyms marked as errors."""


def para(value, kind="paragraph"):
    return {"kind": kind, "text": value}


def table(headers, rows):
    return {"kind": "table", "headers": headers, "rows": rows}


def section(heading, *blocks):
    return {"heading": heading, "blocks": list(blocks)}


TOPICS = []


def add(slug, title, subtitle, sections):
    TOPICS.append({"slug": slug, "unit": 2, "title": title, "subtitle": subtitle,
        "icon": "BookOpenText", "read_minutes": 10, "order": len(TOPICS) + 1,
        "tags": [title, "व्याकरण"], "sections": sections})


