add("karak-vibhakti", "कारक और विभक्ति", "आठ कारक; विभक्ति-चिह्न, शून्य चिह्न और लिखने के नियम", [
    section("कारक का अर्थ", para("संज्ञा या सर्वनाम का वाक्य के अन्य पदों, विशेषतः क्रिया, से जो संबंध होता है उसे कारक कहते हैं। हिंदी की प्रचलित शिक्षण-पद्धति में आठ कारक पढ़ाए जाते हैं। संबंध और संबोधन का क्रिया से सीधा संबंध आवश्यक नहीं।", "definition")),
    section("आठ कारक", table(["कारक", "चिह्न", "उदाहरण"], KARAK)),
    section("विभक्ति : अर्थ और लेखन", para("कारक-संबंध को प्रकट करने वाले रूप या चिह्न विभक्ति कहलाते हैं। हिंदी में ने, को, से, में, पर, का आदि को कारक-चिह्न या परसर्ग भी कहते हैं। संज्ञा से चिह्न अलग लिखते हैं: राम ने, घर में। सर्वनाम के एक चिह्न वाले प्रचलित रूप जुड़े होते हैं: उसने, उसको, मुझसे। संयुक्त चिह्न में अंतिम भाग अलग रहता है: उसके लिए, मुझ पर, उसमें से। हर कारक का चिह्न प्रकट हो, यह आवश्यक नहीं: ‘मोहन सोता है’ में कर्ता का चिह्न शून्य है।")),
    section("अर्थ के आधार पर पहचान", para("‘से’ देखकर करण या अपादान तुरंत न चुनें। ‘कलम से लिखा’ में साधन होने से करण, ‘पेड़ से गिरा’ में अलगाव होने से अपादान है। ‘को’ कर्म तथा संप्रदान दोनों हो सकता है। ‘का/की/के’ का रूप संबंधित वस्तु के लिंग-वचन के अनुसार बदलता है: राम का घर, राम की पुस्तक, राम के मित्र।", "example")),
    section("ने का प्रयोग", para("‘ने’ सामान्यतः सकर्मक क्रिया के पूर्ण भूतकालिक प्रयोग में आता है: सीता ने पुस्तक पढ़ी। हर कर्ता के साथ ‘ने’ नहीं लगता: सीता जाती है। चिह्न के साथ क्रिया-संगति को भी देखें।", "tip"))])

